class Solution {
public:
    vector<int> distanceToCycle(int n, vector<vector<int>>& edges) {
        vector<vector<int>> graph(n);
        vector<int> degree(n);
        for (auto& e : edges) {
            graph[e[0]].push_back(e[1]);
            graph[e[1]].push_back(e[0]);
            ++degree[e[0]]; ++degree[e[1]];
        }
        queue<int> q;
        for (int i = 0; i < n; ++i) if (degree[i] == 1) q.push(i);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            degree[u] = 0;
            for (int v : graph[u]) if (degree[v] > 0 && --degree[v] == 1) q.push(v);
        }
        vector<int> dist(n, -1);
        for (int i = 0; i < n; ++i) if (degree[i] > 0) {
            dist[i] = 0; q.push(i);
        }
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : graph[u]) if (dist[v] == -1) {
                dist[v] = dist[u] + 1; q.push(v);
            }
        }
        return dist;
    }
};
